INSERT INTO `notices` (`title`,`title_my`,`body`,`body_my`,`is_pinned`,`created_at`,`updated_at`) SELECT '비즈니스 인증 안내: 가입 후 영업일 기준 1일 이내 승인','လုပ်ငန်းအတည်ပြုချက် လမ်းညွှန်: စာရင်းသွင်းပြီး အလုပ်ရက် 1 ရက်အတွင်း အတည်ပြုပေးသည်','<p>오프라인 매장, 온라인 판매, 판매 네트워크 중 하나만 증빙하면 됩니다. 매장 사진, 판매 글 캡처, 거래처 대화 캡처 등 사진·캡처도 인정하며, 담당자가 직접 확인한 뒤 승인합니다.</p><p>승인 전에는 상품은 보실 수 있지만 도매가와 주문 신청은 제한됩니다.</p>','<p>ဆိုင်ခန်း (offline ဆိုင်)၊ အွန်လိုင်း ရောင်းချမှု၊ ရောင်းချရေး ကွန်ရက် တစ်ခုခုကိုသာ အထောက်အထား ပြရန် လိုပါသည်။ ဆိုင်ဓာတ်ပုံ၊ ရောင်းချသည့် post screenshot၊ ကုန်သည်များနှင့် စကားပြောထားသည့် screenshot စသည့် ဓာတ်ပုံ·screenshot များကိုလည်း လက်ခံပြီး တာဝန်ခံက ကိုယ်တိုင် စစ်ဆေးပြီးမှ အတည်ပြုပေးပါသည်။</p><p>အတည်ပြုခြင်း မခံရမီ ပစ္စည်းများကို ကြည့်နိုင်သော်လည်း လက်ကားဈေးနှင့် အော်ဒါတင်ခြင်းကို ကန့်သတ်ထားပါသည်။</p>',1,NOW(),NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `settings` WHERE `skey`='initial_data_v1') AND NOT EXISTS (SELECT 1 FROM `notices` WHERE `title`='비즈니스 인증 안내: 가입 후 영업일 기준 1일 이내 승인');
INSERT INTO `notices` (`title`,`title_my`,`body`,`body_my`,`is_pinned`,`created_at`,`updated_at`) SELECT '결제 안내: 주문 신청 후 KBZPay 선불','ငွေပေးချေမှု လမ်းညွှန်: အော်ဒါတင်ပြီး KBZPay ဖြင့် ကြိုတင်ပေးချေရန်','<p>주문 신청 → 안내된 KBZPay 계좌로 송금 → 주문 상세에서 송금자 이름으로 입금 확인 요청 → 입금 확인 후 바로 출고·배송.</p>','<p>အော်ဒါတင်ပါ → ပြထားသော KBZPay အကောင့်သို့ ငွေလွှဲပါ → အော်ဒါ အသေးစိတ်တွင် ငွေလွှဲသူ အမည်ဖြင့် ငွေလက်ခံ အတည်ပြုရန် တောင်းဆိုပါ → ငွေလက်ခံ အတည်ပြုပြီးသည်နှင့် ချက်ချင်း ပစ္စည်းပို့ပေးပါသည်။</p>',1,NOW(),NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `settings` WHERE `skey`='initial_data_v1') AND NOT EXISTS (SELECT 1 FROM `notices` WHERE `title`='결제 안내: 주문 신청 후 KBZPay 선불');
INSERT INTO `settings` (`skey`,`svalue`,`updated_at`) SELECT 'initial_data_v1', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `settings` WHERE `skey`='initial_data_v1');
